-- Read-only: prints the structure of schema public (no data) as one text value. See README-structure-copy.md.
with t as (select c.oid, c.relname, c.relrowsecurity from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p')),
seqs as (select string_agg(format('create sequence if not exists public.%I;', c.relname), E'\n') s from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='S'),
types as (select string_agg(format('create type public.%I as enum (%s);', ty.typname, (select string_agg(quote_literal(e.enumlabel), ',' order by e.enumsortorder) from pg_enum e where e.enumtypid=ty.oid)), E'\n') s from pg_type ty join pg_namespace n on n.oid=ty.typnamespace where n.nspname='public' and ty.typtype='e'),
tabs as (select string_agg(format('create table public.%I (%s);', t.relname, (select string_agg(format('%I %s%s%s', a.attname, format_type(a.atttypid, a.atttypmod), case when d.adbin is not null and a.attgenerated = '' then ' default ' || pg_get_expr(d.adbin, d.adrelid) else '' end, case when a.attnotnull then ' not null' else '' end), ', ' order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=t.oid and a.attnum>0 and not a.attisdropped)), E'\n' order by t.relname) s from t),
cons as (select string_agg(format('alter table public.%I add constraint %I %s;', t.relname, co.conname, pg_get_constraintdef(co.oid)), E'\n' order by case co.contype when 'p' then 0 when 'u' then 1 when 'c' then 2 else 3 end, t.relname) s from t join pg_constraint co on co.conrelid=t.oid),
idx as (select string_agg(i.indexdef || ';', E'\n') s from pg_indexes i where i.schemaname='public' and not exists (select 1 from pg_constraint co where co.conname=i.indexname)),
funcs as (select string_agg(pg_get_functiondef(p.oid) || ';', E'\n' order by p.proname) s from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind in ('f','p') and not exists (select 1 from pg_depend dp where dp.objid=p.oid and dp.deptype='e')),
views as (select string_agg(format('create view public.%I as %s', v.viewname, v.definition), E'\n') s from pg_views v where v.schemaname='public'),
trg as (select string_agg(pg_get_triggerdef(tg.oid) || ';', E'\n') s from pg_trigger tg join t on t.oid=tg.tgrelid where not tg.tgisinternal),
rls as (select string_agg(format('alter table public.%I enable row level security;', relname), E'\n') s from t where relrowsecurity),
pol as (select string_agg(format('create policy %I on public.%I as %s for %s to %s%s%s;', policyname, tablename, permissive, cmd, array_to_string(roles, ','), case when qual is not null then ' using (' || qual || ')' else '' end, case when with_check is not null then ' with check (' || with_check || ')' else '' end), E'\n') s from pg_policies where schemaname='public'),
grt as (select string_agg(format('grant %s on public.%I to %s;', privs, table_name, grantee), E'\n') s from (select table_name, grantee, string_agg(privilege_type, ',') privs from information_schema.role_table_grants where table_schema='public' and grantee in ('anon','authenticated','service_role') group by 1,2) g),
fgrt as (select string_agg(x, E'\n') s from (select format('revoke all on function public.%I(%s) from public, anon, authenticated;', p.proname, pg_get_function_identity_arguments(p.oid)) || case when has_function_privilege('anon', p.oid, 'execute') then format(' grant execute on function public.%I(%s) to anon;', p.proname, pg_get_function_identity_arguments(p.oid)) else '' end || case when has_function_privilege('authenticated', p.oid, 'execute') then format(' grant execute on function public.%I(%s) to authenticated;', p.proname, pg_get_function_identity_arguments(p.oid)) else '' end x from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind='f' and not exists (select 1 from pg_depend dp where dp.objid=p.oid and dp.deptype='e')) y)
select concat_ws(E'\n-- ====\n', '-- types', (select s from types), '-- sequences', (select s from seqs), '-- tables', (select s from tabs), '-- constraints', (select s from cons), '-- indexes', (select s from idx), '-- functions', (select s from funcs), '-- views', (select s from views), '-- triggers', (select s from trg), '-- rls', (select s from rls), '-- policies', (select s from pol), '-- grants', (select s from grt), '-- function grants', (select s from fgrt)) ddl;
